import json
from pathlib import Path

root = Path(__file__).parent
data = json.loads((root / 'concepts.json').read_text())
html = '''<!doctype html>
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Twelve apps, sixty directions</title>
<style>
:root{--paper:#f3eee3;--ink:#243f3e;--muted:#52645f;--line:#c8cec0;--accent:#a3422d;--panel:#fffcf5;--serif:Georgia,'Times New Roman',serif;--sans:'Trebuchet MS',Verdana,sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 var(--sans)}button,a,select{touch-action:manipulation}button,select{font:inherit}button,a{color:inherit}button{cursor:pointer}a{text-underline-offset:4px}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.masthead{border-bottom:1px solid var(--line);padding:18px 5vw;display:flex;align-items:center;justify-content:space-between;gap:20px}.mark{font-weight:800;letter-spacing:-1px;font-size:23px}.edition{font-size:13px;color:var(--muted)}header{padding:60px 5vw 38px;max-width:1500px;margin:auto}h1{font:normal clamp(42px,6.3vw,86px)/1.03 var(--serif);letter-spacing:-3px;margin:0;max-width:900px}header p{max-width:680px;color:var(--muted);font-size:18px;margin-top:25px}.stats{display:flex;gap:30px;flex-wrap:wrap;margin:30px 0 0}.stat b{font-size:25px;margin-right:7px}.stat{font-size:14px}.toolbar{position:sticky;top:0;z-index:2;padding:16px 5vw;background:var(--paper);border-block:1px solid var(--line);display:flex;align-items:center;gap:14px;flex-wrap:wrap}.toolbar label{font-size:14px;font-weight:bold}select{border:1px solid var(--line);border-radius:8px;background:var(--panel);padding:11px 35px 11px 12px;color:var(--ink);max-width:100%}.filter,.download{border:1px solid var(--ink);background:transparent;border-radius:25px;padding:10px 17px;min-height:46px;text-decoration:none;font-size:14px}.filter[aria-pressed=true]{background:var(--ink);color:var(--paper)}.download{margin-left:auto}.count{font-size:13px;color:var(--muted)}main{padding:0 5vw 70px;max-width:1700px;margin:auto}.app{margin-top:55px}.app-head{display:grid;grid-template-columns:1fr 1fr;gap:25px;align-items:end;margin-bottom:25px;padding-bottom:23px;border-bottom:2px solid var(--ink)}h2{font:normal clamp(28px,3vw,43px)/1.1 var(--serif);margin:7px 0}.eyebrow{font-size:13px;letter-spacing:.04em;color:var(--muted)}.app-head p{margin:0;max-width:580px;font-size:15px;color:var(--muted)}.directions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}.direction{border:1px solid var(--line);border-radius:5px 5px 15px 5px;background:var(--panel);overflow:hidden}.screen-button{width:100%;padding:0;border:0;display:block;background:#e3e5d9;aspect-ratio:4/3;overflow:hidden}.screen-button img{width:100%;height:100%;object-fit:contain;display:block;transition:transform .2s}.screen-button:hover img{transform:scale(1.012)}.info{padding:23px}.direction-head{display:flex;gap:12px;justify-content:space-between;align-items:start}.number{font-size:13px;color:var(--accent);display:block;margin-bottom:3px}h3{font:normal 25px/1.2 var(--serif);margin:0}.save{border:1px solid var(--line);background:transparent;border-radius:50%;width:46px;height:46px;flex-shrink:0;font-size:24px}.save[aria-pressed=true]{background:var(--ink);color:var(--paper)}.identity{display:grid;grid-template-columns:130px 1fr;gap:22px;align-items:center;margin:22px 0}.logo-button{width:130px;height:130px;padding:6px;background:#ecebdd;border:0;border-radius:8px}.logo-button img{width:100%;height:100%;object-fit:contain}.tagline{font:normal 23px/1.22 var(--serif);margin:0}.links{display:flex;gap:20px;flex-wrap:wrap;font-size:13px}details{border-top:1px solid var(--line);padding-top:14px;margin-top:20px;font-size:14px;color:var(--muted)}summary{cursor:pointer;min-height:32px;color:var(--ink)}details p{margin:10px 0}.empty{padding:80px 0;text-align:center;color:var(--muted)}footer{border-top:1px solid var(--line);padding:28px 5vw;color:var(--muted);font-size:13px}dialog{border:0;padding:0;max-width:96vw;max-height:96vh;background:var(--paper);color:var(--ink);border-radius:8px}dialog::backdrop{background:#132924df}.dialog-head{display:flex;align-items:center;justify-content:space-between;gap:25px;padding:10px 18px}.dialog-head p{margin:0;font-size:14px}.close{border:1px solid var(--line);border-radius:50%;font-size:24px;width:46px;height:46px;background:transparent}dialog img{display:block;max-width:92vw;max-height:80vh;object-fit:contain;margin:auto;background:#e5e7d9}.status{min-height:24px;font-size:13px;color:var(--muted)}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(min-width:1600px){.directions{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:750px){header{padding-top:35px}h1{letter-spacing:-1.5px}.directions{grid-template-columns:1fr}.app-head{grid-template-columns:1fr}.edition{display:none}.toolbar{gap:9px}.download{margin-left:0}.identity{grid-template-columns:110px 1fr}.logo-button{width:110px;height:110px}.stats{gap:15px}.count{width:100%}.tagline{font-size:21px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}@media print{.toolbar,.save,.links,details,.masthead,dialog{display:none}.directions{grid-template-columns:1fr 1fr}.direction{break-inside:avoid}.app{break-before:page}.screen-button{height:auto}.app-head{display:block}header{padding:0}main{padding:0}.app-head p{margin-top:12px}}
</style></head><body>
<div class="masthead"><span class="mark">School app studies<span style="color:var(--accent)"> /</span></span><span class="edition">Concept collection · October 2026</span></div>
<header><h1>Twelve apps.<br>Sixty ways to see them.</h1><p>Five distinct visual directions for each learning experience. Compare a screen, a logo and a few words that bring each idea into focus.</p><div class="stats"><span class="stat"><b>60</b>screens</span><span class="stat"><b>60</b>logos</span><span class="stat"><b>60</b>taglines</span><span class="stat">iPad first · Web · Desktop</span></div></header>
<div class="toolbar"><label for="app-filter">Explore</label><select id="app-filter"><option value="all">All twelve apps</option></select><button class="filter" id="shortlist" aria-pressed="false">Shortlist only</button><span class="count" id="count" aria-live="polite"></span><a class="download" href="taglines.csv" download>Download tagline CSV ↓</a></div>
<main id="gallery"></main><footer><p>Design explorations, not screenshots of released software. Images were created with the built-in image generation tool. Text and layout in generated artwork may need refinement before implementation.</p><p>Shortlists stay in this browser. Each direction includes an individual screenshot PNG and logo PNG. <a href="README.md">Read the handover notes</a> · <a href="generation/prompts.json" download>Download the full prompt set</a> · <button class="filter" id="export">Export shortlist</button></p><div id="status" class="status" aria-live="polite"></div></footer>
<dialog id="viewer"><div class="dialog-head"><p id="viewer-title"></p><button class="close" aria-label="Close image">×</button></div><img id="viewer-image" alt=""></dialog>
<script>
const apps=__DATA__;
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let shortlist=new Set();try{shortlist=new Set(JSON.parse(localStorage.getItem('school-app-shortlist')||'[]'))}catch{}
let onlyShortlist=false;const filter=document.getElementById('app-filter'),gallery=document.getElementById('gallery');
for(const a of apps){const o=document.createElement('option');o.value=a.slug;o.textContent=a.name;filter.append(o)}
function render(){let count=0;gallery.innerHTML=apps.filter(a=>filter.value==='all'||filter.value===a.slug).map(a=>{const ds=a.directions.filter(d=>!onlyShortlist||shortlist.has(d.folder));if(!ds.length)return '';count+=ds.length;return `<section class="app" aria-labelledby="${a.slug}"><div class="app-head"><div><span class="eyebrow">${escapeHTML(a.area)} · ${escapeHTML(a.years)}</span><h2 id="${a.slug}">${escapeHTML(a.name)}</h2></div><p>${escapeHTML(a.purpose)}</p></div><div class="directions">${ds.map(d=>`<article class="direction"><button class="screen-button" data-view="${d.folder}/screenshot.png" data-title="${escapeHTML(a.name+' · '+d.title+' · Screen')}" aria-label="Enlarge ${escapeHTML(a.name+' '+d.title)} screenshot"><img src="${d.folder}/screenshot.png" alt="${escapeHTML(d.title+' concept screenshot for '+a.name)}" loading="lazy" width="1440" height="1080"></button><div class="info"><div class="direction-head"><div><span class="number">Direction ${String(d.number).padStart(2,'0')}</span><h3>${escapeHTML(d.title)}</h3></div><button class="save" data-save="${d.folder}" aria-label="Shortlist ${escapeHTML(a.name+' '+d.title)}" aria-pressed="${shortlist.has(d.folder)}">${shortlist.has(d.folder)?'★':'☆'}</button></div><div class="identity"><button class="logo-button" data-view="${d.folder}/logo.png" data-title="${escapeHTML(a.name+' · '+d.title+' · Logo')}" aria-label="Enlarge logo"><img src="${d.folder}/logo.png" alt="${escapeHTML(d.logo)}" loading="lazy" width="130" height="130"></button><p class="tagline">${escapeHTML(d.tagline)}</p></div><div class="links"><a href="${d.folder}/screenshot.png" download>Screenshot PNG ↓</a><a href="${d.folder}/logo.png" download>Logo PNG ↓</a></div><details><summary>Behind this direction</summary><p>${escapeHTML(d.style)}</p><p><strong>Screen:</strong> ${escapeHTML(d.screen)}</p><p><strong>Logo:</strong> ${escapeHTML(d.logo)}</p></details></div></article>`).join('')}</div></section>`}).join('')||'<p class="empty">No directions here yet. Use the stars to add a few to your shortlist.</p>';document.getElementById('count').textContent=count+' directions · '+shortlist.size+' shortlisted'}
filter.addEventListener('change',render);document.getElementById('shortlist').addEventListener('click',e=>{onlyShortlist=!onlyShortlist;e.currentTarget.setAttribute('aria-pressed',onlyShortlist);render()});
const viewer=document.getElementById('viewer');gallery.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;shortlist.has(id)?shortlist.delete(id):shortlist.add(id);try{localStorage.setItem('school-app-shortlist',JSON.stringify([...shortlist]))}catch{}render();const restored=document.querySelector('[data-save="'+id+'"]');if(restored)restored.focus();else document.getElementById('shortlist').focus();return}const view=e.target.closest('[data-view]');if(view){document.getElementById('viewer-image').src=view.dataset.view;document.getElementById('viewer-image').alt=view.dataset.title;document.getElementById('viewer-title').textContent=view.dataset.title;viewer.showModal()}});document.querySelector('.close').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});
document.getElementById('export').addEventListener('click',()=>{const selected=apps.flatMap(a=>a.directions.filter(d=>shortlist.has(d.folder)).map(d=>({app:a.name,direction:d.title,tagline:d.tagline,folder:d.folder})));const blob=new Blob([JSON.stringify(selected,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='school-app-shortlist.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('status').textContent='Exported '+selected.length+' shortlisted directions.'});render();
</script></body></html>'''
(root / 'index.html').write_text(html.replace('__DATA__', json.dumps(data, ensure_ascii=False).replace('</', '<\\/')))
print('Gallery built')
